  const vertexBuffer = [];
  function pushVertex(v){ vertexBuffer.push(v.x,v.y,v.z); }
  function getVertexByIndex(index, vertex) {
    const stride = index * 3;
    vertex.x = icosaVerts[stride]; vertex.y = icosaVerts[stride+1]; vertex.z = icosaVerts[stride+2];
  }
  const a={x:0,y:0,z:0}, b={x:0,y:0,z:0}, c={x:0,y:0,z:0};
  function lerp(p,q,t){ return {x:p.x+(q.x-p.x)*t, y:p.y+(q.y-p.y)*t, z:p.z+(q.z-p.z)*t}; }
  function clone(p){ return {x:p.x,y:p.y,z:p.z}; }
  function subdivideFace(a,b,c,detail) {
    const cols = detail + 1;
    const v = [];
    for (let i=0;i<=cols;i++){
      v[i]=[];
      const aj = lerp(a,c,i/cols);
      const bj = lerp(b,c,i/cols);
      const rows = cols - i;
      for (let j=0;j<=rows;j++){
        if (j===0 && i===cols) v[i][j]=aj;
        else v[i][j]=lerp(aj,bj,j/rows);
      }
    }
    for (let i=0;i<cols;i++){
      for (let j=0;j<2*(cols-i)-1;j++){
        const k=Math.floor(j/2);
        if (j%2===0){ pushVertex(v[i][k+1]); pushVertex(v[i+1][k]); pushVertex(v[i][k]); }
        else { pushVertex(v[i][k+1]); pushVertex(v[i+1][k+1]); pushVertex(v[i+1][k]); }
      }
    }
