    getVertexByIndex(icosaIndices[i],a);
    getVertexByIndex(icosaIndices[i+1],b);
    getVertexByIndex(icosaIndices[i+2],c);
    subdivideFace(a,b,c,detail);
  }
  return vertexBuffer.length/3;
}
