/** radialT: 0 = deep interior, 1 = as close to hull as allowed. */
function interiorRadius(shellOuter, districtRadius, radialT) {
  const minR = shellOuter * 0.12;
  const maxR = shellOuter - districtRadius * 1.25;
  return minR + (maxR - minR) * radialT;
}

function placeOnInteriorShell(
  anchorDir,
  offsetU,
  offsetV,
  spread,
  shellOuter,
  districtRadius,
  radialT
) {
  const radial = anchorDir.clone().normalize();
  const r = interiorRadius(shellOuter, districtRadius, radialT);
  const anchor = radial.clone().multiplyScalar(r);
  const { tangent1, tangent2 } = tangentFrame(radial);
  const position = anchor
    .clone()
    .addScaledVector(tangent1, offsetU * spread)
    .addScaledVector(tangent2, offsetV * spread);
  const maxR = shellOuter - districtRadius * 1.1;
  if (position.length() > maxR) position.setLength(maxR);
  return { position, radial: position.clone().normalize(), tangent1, tangent2 };
}

/** Major axis in the tangent plane (orthogonal to radius from asteroid center). */
function orientDistrictMesh(mesh, radial, majorTangent) {
  const zAxis = radial.clone().normalize();
  const yAxis = majorTangent.clone().normalize();
  let xAxis = new THREE.Vector3().crossVectors(yAxis, zAxis);
  if (xAxis.lengthSq() < 1e-8) {
    xAxis = new THREE.Vector3().crossVectors(
      zAxis,
      Math.abs(zAxis.y) < 0.9 ? new THREE.Vector3(0, 1, 0) : new THREE.Vector3(1, 0, 0)
    );
  }
  xAxis.normalize();
  yAxis.crossVectors(zAxis, xAxis).normalize();
  mesh.quaternion.setFromRotationMatrix(
    new THREE.Matrix4().makeBasis(xAxis, yAxis, zAxis)
  );
}

function tangentMajorAxis(radial, tangent1, tangent2, angle) {
  return tangent1
    .clone()
    .multiplyScalar(Math.cos(angle))
    .addScaledVector(tangent2, Math.sin(angle));
}

