/** Interior cluster: district centers stay fully inside the asteroid hull. */
function interiorRadius(shellOuter, districtRadius, radialT) {
  const minR = shellOuter * 0.12;
  const maxR = shellOuter - districtRadius * 1.25;
  return minR + (maxR - minR) * radialT;
}

function placeInInteriorCluster(
  anchorDir,
  offsetU,
  offsetV,
  shellOuter,
  districtRadius,
