function districtWorldCenter(mesh) {
  if (!mesh.geometry.boundingSphere) mesh.geometry.computeBoundingSphere();
  const center = mesh.geometry.boundingSphere.center.clone();
  return mesh.localToWorld(center);
}

function createTubeMaterial() {
  return new THREE.MeshBasicMaterial({
    color: 0x4a7a9a,
    wireframe: true,
    transparent: true,
    opacity: 0.5,
    depthWrite: false,
  });
}

function createStraightTube(from, to, material, radius) {
  const dir = new THREE.Vector3().subVectors(to, from);
  const length = dir.length();
  if (length < 1e-4) return null;
  const curve = new THREE.LineCurve3(from, to);
  const geometry = new THREE.TubeGeometry(curve, 1, radius, 5, false);
  const tube = new THREE.Mesh(geometry, material);
  tube.renderOrder = 0.5;
  return tube;
}

function createKinkedTube(from, to, material, seed, waypointCount, radius) {
  const rng = mulberry32(seed);
  const points = [from.clone()];
  for (let i = 1; i <= waypointCount; i++) {
    const t = i / (waypointCount + 1);
    const point = from.clone().lerp(to, t);
    point.x += (rng() - 0.5) * 2.6;
    point.y += (rng() - 0.5) * 2.6;
    point.z += (rng() - 0.5) * 0.55;
    points.push(point);
  }
  points.push(to.clone());
  const curve = new THREE.CatmullRomCurve3(points);
  const geometry = new THREE.TubeGeometry(curve, 18, radius, 5, false);
  const tube = new THREE.Mesh(geometry, material);
  tube.renderOrder = 0.5;
  return tube;
}

