        center: new THREE.Vector3(spec.x, spec.y, spec.z),
        radius: spec.radius * 1.06,
      });
      parts.push(geom);
    }

    const kept = [];
    for (let p = 0; p < parts.length; p++) {
      const pos = parts[p].attributes.position;
      for (let t = 0; t < pos.count; t += 3) {
