  function defaultSpheroidLayout(seed, spread, radius) {
    const rng = mulberry32(seed);
    const specs = [];
    const offsetXY = spread * 0.82;
    const offsetZ = spread * 0.22;
    for (let i = 0; i < SPHEROIDS_PER_DISTRICT; i++) {
      specs.push({
        x: (rng() - 0.5) * offsetXY,
        y: (rng() - 0.5) * offsetXY,
        z: (rng() - 0.5) * offsetZ,
